// 5 Node, dramatik 5 dakikalık senaryo
const SCENARIO = [
  { time: "00:00", node_id: "1", event_type: "NORMAL",          message: "[INFO: BR] IPv6 addresses: fe80::201:1:1:1" },
  { time: "00:10", node_id: "2", event_type: "NORMAL",          message: "[INFO: App] UDP packet sent to server" },
  { time: "00:20", node_id: "3", event_type: "NORMAL",          message: "[INFO: App] UDP packet sent to server" },
  { time: "00:30", node_id: "4", event_type: "NORMAL",          message: "[INFO: App] UDP packet sent to server" },
  { time: "00:40", node_id: "5", event_type: "NORMAL",          message: "[INFO: App] UDP packet sent to server" },
  { time: "00:50", node_id: "3", event_type: "ROUTING_FAILURE", message: "[INFO: App] Not reachable yet" },
  { time: "01:10", node_id: "3", event_type: "TOPOLOGY_CHANGE", message: "[INFO: RPL] parent switch from node2 to node1" },
  { time: "01:30", node_id: "4", event_type: "TOPOLOGY_CHANGE", message: "[INFO: RPL] parent switch from node3 to node2" },
  { time: "01:50", node_id: "3", event_type: "ROUTING_FAILURE", message: "[INFO: App] Not reachable yet" },
  { time: "02:10", node_id: "3", event_type: "NODE_FAILURE",    message: "[ERROR] Node heartbeat timeout after 3 retries" },
  { time: "02:30", node_id: "5", event_type: "ROUTING_FAILURE", message: "[INFO: App] Not reachable yet" },
  { time: "02:50", node_id: "2", event_type: "TOPOLOGY_CHANGE", message: "[INFO: RPL] parent switch from node3 to node1" },
  { time: "03:10", node_id: "3", event_type: "ROUTING_FAILURE", message: "[INFO: App] Attempting reconnection..." },
  { time: "03:30", node_id: "3", event_type: "NORMAL",          message: "[INFO: App] Reconnected. UDP packet sent" },
  { time: "03:50", node_id: "5", event_type: "NORMAL",          message: "[INFO: App] UDP packet sent to server" },
  { time: "04:10", node_id: "4", event_type: "NORMAL",          message: "[INFO: App] UDP packet sent to server" },
  { time: "04:30", node_id: "2", event_type: "NORMAL",          message: "[INFO: App] Network stable, UDP sent" },
  { time: "04:50", node_id: "1", event_type: "NORMAL",          message: "[INFO: BR] All nodes reachable" },
];

// Kaç kez çalıştığını takip et
const staticData = $getWorkflowStaticData('global');
if (staticData.index === undefined) staticData.index = 0;

const log = SCENARIO[staticData.index % SCENARIO.length];
staticData.index++;

const timestamp = Date.now();

return [{
  json: {
    timestamp: String(timestamp),
    node_id: log.node_id,
    event_type: log.event_type,
    message: log.message,
    raw_line: `${timestamp} ID:${log.node_id} ${log.message}`,
    scenario_time: log.time,
    replay_mode: true
  }
}];
